{"code": "import pytest
import impl


class TestFormatAmountNormalPath:
    """Test basic successful usage"""

    def test_simple_positive_usd(self):
        result = impl.format_amount("100.50", "USD", {"USD": 2})
        assert result == "100.50"

    def test_simple_positive_jpy_no_decimals(self):
        result = impl.format_amount("1234.5", "JPY", {"JPY": 0})
        assert result == "1234"
        assert "." not in result

    def test_simple_positive_kwd_three_decimals(self):
        result = impl.format_amount("100.567", "KWD", {"KWD": 3})
        assert result == "100.567"

    def test_simple_positive_clf_four_decimals(self):
        result = impl.format_amount("100.1234", "CLF", {"CLF": 4})
        assert result == "100.1234"

    def test_negative_amount_preserves_sign(self):
        result = impl.format_amount("-50.25", "USD", {"USD": 2})
        assert result == "-50.25"

    def test_zero_with_appropriate_decimals(self):
        result = impl.format_amount("0", "USD", {"USD": 2})
        assert result == "0.00"

    def test_zero_jpy_no_decimals(self):
        result = impl.format_amount("0", "JPY", {"JPY": 0})
        assert result == "0"


class TestFormatAmountRounding:
    """Test ROUND_HALF_EVEN banker's rounding"""

    def test_round_half_even_up_to_even(self):
        """2.675 rounds to 2.68 (8 is even)"""
        result = impl.format_amount("2.675", "USD", {"USD": 2})
        assert result == "2.68"

    def test_round_half_even_down_to_even(self):
        """2.665 rounds to 2.66 (6 is even)"""
        result = impl.format_amount("2.665", "USD", {"USD": 2})
        assert result == "2.66"

    def test_round_halfway_negative_symmetric(self):
        result = impl.format_amount("-2.675", "USD", {"USD": 2})
        assert result == "-2.68"

    def test_round_down_extra_decimals(self):
        result = impl.format_amount("1.234567", "USD", {"USD": 2})
        assert result == "1.23"

    def test_round_up_with_extra_decimals(self):
        result = impl.format_amount("1.236", "USD", {"USD": 2})
        assert result == "1.24"


class TestFormatAmountExponentZero:
    """Test exponent 0 (no fractional part, no decimal point)"""

    def test_exponent_0_rounds_to_integer(self):
        result = impl.format_amount("1234.567", "JPY", {"JPY": 0})
        assert result == "1235"
        assert "." not in result

    def test_exponent_0_negative(self):
        result = impl.format_amount("-1234.567", "JPY", {"JPY": 0})
        assert result == "-1235"

    def test_negative_zero_becomes_unsigned_zero(self):
        """Test -0.4 in JPY becomes 0, not -0"""
        result = impl.format_amount("-0.4", "JPY", {"JPY": 0})
        assert result == "0"
        assert not result.startswith("-")


class TestFormatAmountVariousExponents:
    """Test different exponent values"""

    def test_exponent_1(self):
        result = impl.format_amount("10.567", "TEST1", {"TEST1": 1})
        assert result == "10.6"

    def test_exponent_3(self):
        result = impl.format_amount("100.1", "KWD", {"KWD": 3})
        assert result == "100.100"

    def test_exponent_4(self):
        result = impl.format_amount("100.1", "CLF", {"CLF": 4})
        assert result == "100.1000"


class TestFormatAmountParsing:
    """Test various amount string formats"""

    def test_scientific_notation_positive_exponent(self):
        result = impl.format_amount("1E+2", "USD", {"USD": 2})
        assert result == "100.00"

    def test_scientific_notation_negative_exponent(self):
        result = impl.format_amount("-1.5e-3", "USD", {"USD": 2})
        assert result == "-0.00"

    def test_whitespace_around_amount(self):
        result = impl.format_amount("  100.50  ", "USD", {"USD": 2})
        assert result == "100.50"

    def test_explicit_positive_sign_removed(self):
        result = impl.format_amount("+100.50", "USD", {"USD": 2})
        assert result == "100.50"
        assert not result.startswith("+")

    def test_fewer_decimals_than_needed_zero_padded(self):
        result = impl.format_amount("123.4", "USD", {"USD": 2})
        assert result == "123.40"

    def test_no_decimal_point_in_input(self):
        result = impl.format_amount("100", "USD", {"USD": 2})
        assert result == "100.00"

    def test_decimal_point_only(self):
        result = impl.format_amount("100.", "USD", {"USD": 2})
        assert result == "100.00"


class TestFormatAmountNegativeZero:
    """Test negative zero handling"""

    def test_negative_zero_usd(self):
        """Test -0.004 in USD becomes 0.00"""
        result = impl.format_amount("-0.004", "USD", {"USD": 2})
        assert result == "0.00"
        assert not result.startswith("-")

    def test_very_small_negative_rounds_to_zero(self):
        result = impl.format_amount("-0.001", "USD", {"USD": 2})
        assert result == "0.00"


class TestFormatAmountErrors:
    """Test error conditions and validation"""

    def test_unknown_currency_raises_keyerror(self):
        with pytest.raises(KeyError):
            impl.format_amount("100.00", "XXX", {"USD": 2})

    def test_currency_checked_before_amount_validation(self):
        """Unknown currency raises KeyError even with invalid amount"""
        with pytest.raises(KeyError):
            impl.format_amount("not_a_number", "XXX", {"USD": 2})

    def test_empty_amount_string(self):
        with pytest.raises(ValueError):
            impl.format_amount("", "USD", {"USD": 2})

    def test_non_numeric_amount(self):
        with pytest.raises(ValueError):
            impl.format_amount("abc", "USD", {"USD": 2})

    def test_multiple_decimal_points(self):
        with pytest.raises(ValueError):
            impl.format_amount("1.2.3", "USD", {"USD": 2})

    def test_comma_separator_invalid(self):
        with pytest.raises(ValueError):
            impl.format_amount("12,34", "USD", {"USD": 2})

    def test_currency_symbol_invalid(self):
        with pytest.raises(ValueError):
            impl.format_amount("$1.00", "USD", {"USD": 2})

    def test_thousands_separator_invalid(self):
        with pytest.raises(ValueError):
            impl.format_amount("1 000.00", "USD", {"USD": 2})

    def test_nan_invalid(self):
        with pytest.raises(ValueError):
            impl.format_amount("NaN", "USD", {"USD": 2})

    def test_snan_invalid(self):
        with pytest.raises(ValueError):
            impl.format_amount("sNaN", "USD", {"USD": 2})

    def test_infinity_invalid(self):
        with pytest.raises(ValueError):
            impl.format_amount("Infinity", "USD", {"USD": 2})

    def test_negative_infinity_invalid(self):
        with pytest.raises(ValueError):
            impl.format_amount("-Infinity", "USD", {"USD": 2})


class TestFormatAmountCaseSensitivity:
    """Test that currency codes are case-sensitive"""

    def test_lowercase_currency_code_fails(self):
        with pytest.raises(KeyError):
            impl.format_amount("100.00", "usd", {"USD": 2})

    def test_mixed_case_currency_code_fails(self):
        with pytest.raises(KeyError):
            impl.format_amount("100.00", "Usd", {"USD": 2})


class TestFormatAmountEdgeCases:
    """Test edge cases and boundary conditions"""

    def test_very_large_amount(self):
        result = impl.format_amount("999999999999999999.99", "USD", {"USD": 2})
        assert result == "999999999999999999.99"

    def test_very_small_amount_rounds_to_zero(self):
        result = impl.format_amount("0.001", "USD", {"USD": 2})
        assert result == "0.00"

    def test_large_negative_amount(self):
        result = impl.format_amount("-999999999999.99", "USD", {"USD": 2})
        assert result == "-999999999999.99"

    def test_amount_already_at_correct_precision(self):
        result = impl.format_amount("123.45", "USD", {"USD": 2})
        assert result == "123.45"
"}
